1547	            if constexpr (PINGPONG) nb_arrive(PP_BASE + (1 - cwg), PP_CNT);  // release the other WG
1548	            wgmma_wait1();
1549	            if constexpr (EXTRA) { if (softcap > 0.f) pf_softcap<CN>(s, scale, softcap);
1550	                                   pf_mask_win<CN>(s, nb * CN, qpos_lo, qpos_hi, t.seqlen_k, causal, win_l, win_r, tg); }
1551	            else                   pf_mask<CN>(s, nb * CN, qpos_lo, qpos_hi, t.seqlen_k, causal, tg);
1552	            sc[0] = softmax_stats<CN>(s, m_r, l_r, 0, li, t.s2);
1553	            sc[1] = softmax_stats<CN>(s, m_r, l_r, 1, li, t.s2);
1554	            wgmma_wait0();
1555	#pragma unroll
1556	            for (int i = 0; i < CN / 4; ++i) P[i] = pack_2x<TC>(s[2*i], s[2*i+1]);
