1558	        }
1559	        rescale_o_g(acc_o, sc);
1560	        pv_final_g<TC, HDVsm, CN>(acc_o, P, sV_a + ((gbase + t.n_cnt - 1) % STAGES) * stV_bytes);
1561	        mbar_arrive(&empty[(gbase + t.n_cnt - 1) % STAGES]);
