1571	            bool val = idx < t.Mrows;
1572	            int token = idx / rep, qhead = t.hk * rep + idx % rep, qidx = t.q0 + token;
1573	            float mr = m_r[r];
1574	            if (s_aux != nullptr) {                       // attention sink: extra logit in the denom (see prefill_kernel)
