2484	template <typename TIn, typename TOut, int HD, int HDV, int MAXM>
2485	__global__ void decode_kernel(
2486	        const TIn* __restrict__ Q, const TIn* __restrict__ K, const TIn* __restrict__ V,
2487	        float* __restrict__ Opart, float* __restrict__ LSEpart,
2488	        const int* __restrict__ cu_q, const int* __restrict__ cu_k, const int* __restrict__ seqused_k,
2489	        const int* __restrict__ page_table,
2490	        const float* __restrict__ q_descale, const float* __restrict__ k_descale, const float* __restrict__ v_descale,
2491	        int ds_b, int ds_h,
2492	        long q_row, long q_head, long k_row, long k_head, long v_row, long v_head,
2493	        int batch, int hq, int hkv, int rep, int total_q, int block_size, int page_stride,
2494	        int num_splits, float scale, float softcap, int win_l, int win_r, int causal) {
2495	    constexpr int per = HD / 32, perv = HDV / 32;
2496	    const int witem = blockIdx.x * WARPS_PER_BLOCK + (threadIdx.x >> 5);
2497	    const int lane = threadIdx.x & 31;
2498	    if (witem >= num_splits * hkv * batch) return;
2499	    // work-item -> (b, hk, split)
2500	    const int split = witem % num_splits;
2501	    int tmp = witem / num_splits;
2502	    const int hk = tmp % hkv;
2503	    const int b = tmp / hkv;
2504	    // b is bounded by the launch (grid sized to batch); guard:
2505	    const int q0 = cu_q[b];
2506	    const int sq = cu_q[b + 1] - q0;
2507	    if (sq <= 0) return;
2508	    const int klen = seqused_k ? seqused_k[b] : (cu_k[b + 1] - cu_k[b]);
2509	    const int M = sq * rep;
2510	
2511	    const long ds_idx = (long)b * ds_b + (long)hk * ds_h;
2512	    const float qd = q_descale ? q_descale[ds_idx] : 1.f;
2513	    const float kd = k_descale ? k_descale[ds_idx] : 1.f;
2514	    const float vd = v_descale ? v_descale[ds_idx] : 1.f;
2515	    const float qk_scale = scale * qd * kd;
2516	
2517	    // split's key range
2518	    const int span = (klen + num_splits - 1) / num_splits;
2519	    const int jlo = split * span;
2520	    const int jhi = min(jlo + span, klen);
2521	
2522	    float qreg[MAXM][per];
2523	    float acc[MAXM][perv];
2524	    float mrow[MAXM], lrow[MAXM];
2525	    int qabs[MAXM];
2526	#pragma unroll
2527	    for (int mi = 0; mi < MAXM; ++mi) {
2528	        if (mi >= M) break;
2529	        const int qpos = mi / rep, r = mi % rep;
2530	        const int head = hk * rep + r;
2531	        const TIn* qp = Q + (long)(q0 + qpos) * q_row + (long)head * q_head;
2532	#pragma unroll
2533	        for (int e = 0; e < per; ++e) qreg[mi][e] = to_float<TIn>(qp[lane * per + e]);
2534	#pragma unroll
2535	        for (int e = 0; e < perv; ++e) acc[mi][e] = 0.f;
2536	        mrow[mi] = -INFINITY; lrow[mi] = 0.f;
2537	        qabs[mi] = klen - sq + qpos;
2538	    }
2539	
2540	    // Software-pipelined K/V load: issue key (j+1)'s gmem loads (including the dependent page_table
2541	    // lookup) while computing on key j, so the load latency overlaps the (short) softmax compute.
2542	    auto load_key = [&](int j, float* kx, float* vx) {
2543	        long krow;
2544	        if (page_table) { int blk = page_table[(long)b * page_stride + j / block_size]; krow = (long)blk * block_size + (j % block_size); }
