2547	        const TIn* vp = V + krow * v_row + (long)hk * v_head;
2548	#pragma unroll
2549	        for (int e = 0; e < per; ++e)  kx[e] = to_float<TIn>(kp[lane * per + e]);
2550	#pragma unroll
2551	        for (int e = 0; e < perv; ++e) vx[e] = to_float<TIn>(vp[lane * perv + e]);
2552	    };
2553	    float kxA[per], vxA[perv], kxB[per], vxB[perv];
2554	    if (jlo < jhi) load_key(jlo, kxA, vxA);
2555	    for (int j = jlo; j < jhi; ++j) {
2556	        const bool A = ((j - jlo) & 1) == 0;
2557	        float* kx = A ? kxA : kxB; float* vx = A ? vxA : vxB;
2558	        if (j + 1 < jhi) load_key(j + 1, A ? kxB : kxA, A ? vxB : vxA);   // prefetch next
2559	#pragma unroll
2560	        for (int mi = 0; mi < MAXM; ++mi) {
2561	            if (mi >= M) break;
2562	            const int qa = qabs[mi];
2563	            bool masked = (causal && j > qa) || (win_l >= 0 && j < qa - win_l) || (win_r >= 0 && j > qa + win_r);
2564	            float dot = 0.f;
2565	#pragma unroll
2566	            for (int e = 0; e < per; ++e) dot += qreg[mi][e] * kx[e];
2567	            float s = wreduce_sum(dot) * qk_scale;
2568	            if (softcap > 0.f) s = softcap * tanhf(s / softcap);
2569	            if (masked) continue;
2570	            float mnew = fmaxf(mrow[mi], s);
2571	            float corr = __expf(mrow[mi] - mnew), p = __expf(s - mnew);
2572	            lrow[mi] = lrow[mi] * corr + p;
2573	#pragma unroll
2574	            for (int e = 0; e < perv; ++e) acc[mi][e] = acc[mi][e] * corr + p * (vx[e] * vd);
2575	            mrow[mi] = mnew;
2576	        }
2577	    }
2578	
2579	#pragma unroll
2580	    for (int mi = 0; mi < MAXM; ++mi) {
2581	        if (mi >= M) break;
2582	        const int qpos = mi / rep, r = mi % rep;
2583	        const int head = hk * rep + r, qidx = q0 + qpos;
2584	        const float inv = lrow[mi] > 0.f ? 1.f / lrow[mi] : 0.f;
2585	        float* op = Opart + (((long)split * total_q + qidx) * hq + head) * HDV;
2586	#pragma unroll
2587	        for (int e = 0; e < perv; ++e) op[lane * perv + e] = acc[mi][e] * inv;
