2681	    int block_size = paged ? (int)k.size(1) : 0;
2682	    int page_stride = paged ? (int)page_table->stride(0) : 0;
2683	
2684	    // num_splits: forced when cfg>0, else split aggressively for occupancy (this warp path is 1 warp /
2685	    // work-item, so more splits = more resident warps). Don't split finer than 64 keys/split.
2686	    int num_splits;
2687	    if (cfg_splits > 0) num_splits = cfg_splits;
2688	    else {
2689	        int dev = 0; cudaGetDevice(&dev);
2690	        int sms = 132; cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, dev);
2691	        int base = hkv * b;
2692	        int want = (8 * sms * WARPS_PER_BLOCK + base - 1) / (base > 0 ? base : 1);
2693	        int cap = (max_klen + 63) / 64;
2694	        num_splits = std::max(1, std::min(std::min(want, cap), 64));
2695	    }
2696	
2697	    int ds_b = qd ? (int)qd->stride(0) : 0, ds_h = qd ? (int)qd->stride(1) : 0;
2698	    auto fopt = q.options().dtype(at::kFloat);
2699	    at::Tensor Opart = at::empty({(long)num_splits, total_q, hq, HDV}, fopt);
2700	    at::Tensor LSEpart = at::empty({(long)num_splits, hq, total_q}, fopt);
2701	
2702	    int witems = num_splits * hkv * b;
2703	    int blocks = (witems + WARPS_PER_BLOCK - 1) / WARPS_PER_BLOCK;
2704	    dim3 grid((unsigned)blocks, 1, 1);
2705	    decode_kernel<TIn, TOut, HD, HDV, MAXM><<<grid, DEC_THREADS, 0, stream>>>(
2706	        (const TIn*)q.data_ptr(), (const TIn*)k.data_ptr(), (const TIn*)v.data_ptr(),
2707	        (float*)Opart.data_ptr(), (float*)LSEpart.data_ptr(),
2708	        (const int*)cu_q.data_ptr(), cu_k ? (const int*)cu_k->data_ptr() : nullptr,
2709	        seqused_k ? (const int*)seqused_k->data_ptr() : nullptr,
2710	        paged ? (const int*)page_table->data_ptr() : nullptr,
2711	        qd ? (const float*)qd->data_ptr() : nullptr, kd ? (const float*)kd->data_ptr() : nullptr,
2712	        vd ? (const float*)vd->data_ptr() : nullptr, ds_b, ds_h,
2713	        q_row, q_head, k_row, k_head, v_row, v_head,
2714	        b, hq, hkv, rep, total_q, block_size, page_stride, num_splits,
2715	        (float)scale, (float)softcap, win_l, win_r, causal ? 1 : 0);
2716	
2717	    combine_kernel<TOut, HDV><<<dim3((unsigned)(total_q * hq), (unsigned)combine_nb(HDV)), COMBINE_THREADS, 0, stream>>>(
2718	        (const float*)Opart.data_ptr(), (const float*)LSEpart.data_ptr(),
2719	        (TOut*)out.data_ptr(), (float*)lse.data_ptr(), num_splits, total_q, hq, o_row, o_head);
2720	}
