2722	// Dispatch on (HD,HDV) and the packed-GQA row bound MAXM (rounded to 4/8/16 to bound registers).
2723	template <typename TIn, typename TOut>
2724	static void launch_decode(const at::Tensor& q, const at::Tensor& k, const at::Tensor& v,
2725	                          at::Tensor& out, at::Tensor& lse, const at::Tensor& cu_q,
2726	                          const std::optional<at::Tensor>& cu_k, const std::optional<at::Tensor>& seqused_k,
2727	                          const std::optional<at::Tensor>& page_table,
2728	                          const std::optional<at::Tensor>& qd, const std::optional<at::Tensor>& kd,
2729	                          const std::optional<at::Tensor>& vd,
2730	                          int b, int hq, int hkv, int hd, int hdv, int total_q, int max_q, int cfg_splits,
2731	                          double scale, double softcap, int win_l, int win_r, bool causal, int max_klen,
2732	                          cudaStream_t stream) {
2733	    int rep = hq / hkv;
2734	    int maxM = max_q * rep;
2735	    int mm = maxM <= 4 ? 4 : (maxM <= 8 ? 8 : 16);
2736	    TORCH_CHECK(maxM <= 16, "decode: packed-GQA rows ", maxM, " > 16 unsupported");
2737	#define DEC_DISP(HD_, HDV_, MM_)                                                                     \
2738	    launch_decode_t<TIn, TOut, HD_, HDV_, MM_>(q, k, v, out, lse, cu_q, cu_k, seqused_k, page_table, \
2739	        qd, kd, vd, b, hq, hkv, total_q, cfg_splits, scale, softcap, win_l, win_r, causal, max_klen, stream)
2740	#define DEC_BY_MM(HD_, HDV_) do { if (mm == 4) DEC_DISP(HD_, HDV_, 4); else if (mm == 8) DEC_DISP(HD_, HDV_, 8); else DEC_DISP(HD_, HDV_, 16); } while (0)
2741	    if (hd == 128 && hdv == 128)      DEC_BY_MM(128, 128);
2742	    else if (hd == 64 && hdv == 64)   DEC_BY_MM(64, 64);
2743	    else if (hd == 96 && hdv == 96)   DEC_BY_MM(96, 96);
2744	    else if (hd == 192 && hdv == 192) DEC_BY_MM(192, 192);
2745	    else if (hd == 256 && hdv == 256) DEC_BY_MM(256, 256);
2746	    else if (hd == 192 && hdv == 128) DEC_BY_MM(192, 128);
2747	    else TORCH_CHECK(false, "decode: unsupported hd/hdv ", hd, "/", hdv);
2748	#undef DEC_BY_MM
2749	#undef DEC_DISP
2750	}
