2772	template <typename TIn, typename TC, int HD, int HDV>
2773	static void launch_decode_split(const at::Tensor& q, const at::Tensor& k, const at::Tensor& v,
2774	                                at::Tensor& out, at::Tensor& lse, const at::Tensor& cu_q,
2775	                                const std::optional<at::Tensor>& cu_k, const std::optional<at::Tensor>& seqused_k,
2776	                                const std::optional<at::Tensor>& page_table,
2777	                                const std::optional<at::Tensor>& qd_, const std::optional<at::Tensor>& kd_,
2778	                                const std::optional<at::Tensor>& vd_,
2779	                                int b, int hq, int hkv, int total_q, int max_q, int max_klen, int cfg_splits,
2780	                                double scale, bool causal, double softcap, int win_l, int win_r,
2781	                                const int* leftpad_k, cudaStream_t stream) {
2782	    using namespace pf;
2783	    const bool paged = page_table.has_value();
2784	    int rep = hq / hkv;
2785	    long q_row = q.stride(0), q_head = q.stride(1);
2786	    long k_row, k_head, v_row, v_head;
2787	    if (paged) { k_row = k.stride(1); k_head = k.stride(2); v_row = v.stride(1); v_head = v.stride(2); }
2788	    else       { k_row = k.stride(0); k_head = k.stride(1); v_row = v.stride(0); v_head = v.stride(1); }
2789	    long o_row = out.stride(0), o_head = out.stride(1);
2790	    int block_size = paged ? (int)k.size(1) : 0;
2791	    int page_stride = paged ? (int)page_table->stride(0) : 0;
2792	    const float* qd = qd_ ? (const float*)qd_->data_ptr() : nullptr;
2793	    const float* kd = kd_ ? (const float*)kd_->data_ptr() : nullptr;
2794	    const float* vd = vd_ ? (const float*)vd_->data_ptr() : nullptr;
2795	    int ds_b = qd_ ? (int)qd_->stride(0) : 0, ds_h = qd_ ? (int)qd_->stride(1) : 0;
2796	
2797	    // Key-tile width (DCN) + STAGES, chosen per EFFECTIVE context length. hd128 has two regimes:
2798	    //   wide (DCN=128, STAGES=3): moderate ctx -> wgmma n-width + fewer/meatier splits win;
2799	    //   deep (DCN=64,  STAGES=5): long ctx     -> deeper K/V pipeline hides DRAM latency.
2800	    // Larger head dims are smem-forced narrow (192->64, 256->48) so wide==deep (single instantiation).
2801	    constexpr int DHDsm = ((HD + 63) / 64) * 64, DHDVsm = ((HDV + 63) / 64) * 64;
2802	    // hd256: non-windowed (deep) wants wider CN=64 (fewer/meatier tiles amortize the wasted-M
2803	    // softmax; STAGES=3 still fits smem); windowed+softcap (gemma2, wide) keeps CN=48/STAGES=4
2804	    // (the deeper K/V pipeline hides the extra tanh/mask latency better than wider tiles).
2805	    constexpr int DCN_W = (HD == 256) ? 48 : (HD == 192) ? 64 : CTA_N;   // hd128 -> 128
2806	    constexpr int DCN_D = (HD == 256) ? 64 : (HD == 192) ? 64 : 64;      // hd128 -> 64
2807	    // Deep path occupancy. NCU shows the deep decode is occupancy/latency-bound, NOT bandwidth-bound:
2808	    // ~8% achieved occupancy (1 consumer WG == 4 active warps), DRAM only ~56% peak, top stalls
2809	    // wait(wgmma)+long-scoreboard(loads). Adding warps that do WASTED-M work does not help: a 2nd
2810	    // consumer WG (CM=128) regresses (it computes 64 dead rows that contend for issue slots), and a
2811	    // 2nd CTA (DEEP2) costs pipeline depth on hd128. DEEP2 (2 CTA/SM) is kept ONLY for the compute-
2812	    // heavier HD>=192 small-value decode (diffv: enough real wgmma work to overlap a 2nd CTA).
2813	    // DCM=64 => single consumer warpgroup (decode is tiny-M; a 2nd WG would be fully masked).
2814	    constexpr int DCM = 64;
2815	    constexpr int DST_D2 = ds_fit_stages(DCN_D, DHDsm, DHDVsm, DCM, 2);  // 2 CTA/SM
2816	    constexpr bool DEEP2 = (HDV <= 128) && (HD >= 192) && (DST_D2 >= 2);
2817	    constexpr int DCM_DEEP = DCM, DCM_W = DCM;
2818	    constexpr int DST_D = DEEP2 ? DST_D2 : ds_fit_stages(DCN_D, DHDsm, DHDVsm, DCM, 1);
2819	    constexpr int MINB_D = DEEP2 ? 2 : 1;
2820	    constexpr int DST_W = ds_fit_stages(DCN_W, DHDsm, DHDVsm, DCM);
2821	    // Deep (narrow-CN, STAGES=5) for plain non-windowed hd128 -> hides DRAM latency. Windowed (SWA)
2822	    // hd128 uses the wide path: split-KV over a sliding window leaves the deep pipeline mostly unfilled
2823	    // (few in-window tiles/split), so wider tiles + GPU-filling split count measure better.
2824	    // "deep" = the DRAM-latency-hiding regime (4-wave split target + >=2-tiles/split pipeline-fill
2825	    // guard). hd128 long-ctx gets it via the narrow DCN (DCN_W!=DCN_D); the big head dims (>=192) are
2826	    // ALREADY smem-forced narrow (DCN_W==DCN_D) and run 1 CTA/SM, so they want the same treatment
2827	    // (fill the 4-5 stage K/V pipeline + spread enough CTAs across SMs). Windowed stays wide.
2828	    const bool deep = ((DCN_W != DCN_D) || (HD >= 192)) && (win_l < 0) && (win_r < 0);
2829	    const int DCN = deep ? DCN_D : DCN_W;
2830	    const int DCM_RUN = deep ? DCM_DEEP : DCM_W;
2831	    int tiles_m = (max_q * rep + DCM_RUN - 1) / DCM_RUN;
2832	    // n_max key-tiles (causal: last query attends all keys -> ceil(klen/CN)); cap splits to it.
2833	    int n_max_est = (max_klen + DCN - 1) / DCN;
2834	    int dev = 0; cudaGetDevice(&dev);
2835	    int sms = 132; cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, dev);
2836	    int base = tiles_m * hkv * b;   // resident CTAs (hkv*batch tiles) before splitting
2837	    int num_splits;
2838	    if (cfg_splits > 0) num_splits = cfg_splits;
2839	    else {
2840	        // Wave-quantization-aware split count. An NCU split sweep across the whole decode family
2841	        // shows the optimum is the LARGEST split count that still fits in ~ONE occupancy wave
2842	        // (base*splits ~ sms*bps): splitting past one wave adds a partial-wave tail (those SMs cost
2843	        // a FULL wave of latency) plus per-split Q-load + combine overhead, which strictly regresses
2844	        // -- e.g. gemma2 0.99@2 -> 0.79@3 -> 0.82@5, blk32 0.98@2 -> 0.80@12. The old 2-4 wave target
2845	        // therefore over-split every shape. bps = co-resident CTAs/SM (DEEP2 packs 2/SM, else 1/SM),
2846	        // so one wave is sms*bps CTAs. n_max_est (below) clamps to available key-tiles.
2847	        int bps = deep ? MINB_D : 1;
2848	        int want = std::max(1, (sms * bps) / (base > 0 ? base : 1));
2849	        num_splits = std::min(want, deep ? 48 : 32);
2850	    }
2851	    if (num_splits > n_max_est) num_splits = std::max(1, n_max_est);
2852	
2853	    bool use_tma = std::is_same<TIn, TC>::value && (HD % 64 == 0) && (HDV % 64 == 0) &&
2854	                   paged && block_size > 0 && (DCN % block_size == 0) && (block_size % 8 == 0) &&
2855	                   (k.stride(0) == (int64_t)block_size * k.stride(1)) &&
2856	                   (v.stride(0) == (int64_t)block_size * v.stride(1)) &&
2857	                   k.stride(3) == 1 && v.stride(3) == 1;
2858	    CUtensorMap mapK{}, mapV{};
2859	    if (use_tma) { mapK = make_kv_map<TC>(k, block_size); mapV = make_kv_map<TC>(v, block_size); }
2860	
2861	    const bool extra = (softcap > 0.0) || (win_l >= 0) || (win_r >= 0) || (leftpad_k != nullptr);
2862	#define DS_LAUNCH(TMA_, EXTRA_, DCN_, DST_, DCM_, MINB_, NS_, OP_, LP_)                                 \
2863	    launch_prefill_t<TIn, TC, HD, HDV, TMA_, EXTRA_, DST_, DCN_, DCM_, MINB_>(q, k, v, out, lse, cu_q, cu_k, seqused_k, page_table, \
2864	        mapK, mapV, hkv, rep, total_q, block_size, page_stride, tiles_m, b, scale, causal,              \
2865	        softcap, win_l, win_r, q_row, q_head, k_row, k_head, v_row, v_head, o_row, o_head, NS_, OP_, LP_, \
2866	        qd, kd, vd, ds_b, ds_h, nullptr, leftpad_k, stream)
2867	#define DS_BY_TMA(EXTRA_, DCN_, DST_, DCM_, MINB_, NS_, OP_, LP_)                                       \
2868	    do { if (use_tma) DS_LAUNCH(true, EXTRA_, DCN_, DST_, DCM_, MINB_, NS_, OP_, LP_);                  \
2869	         else         DS_LAUNCH(false, EXTRA_, DCN_, DST_, DCM_, MINB_, NS_, OP_, LP_); } while (0)
2870	#define DS_BY_EXTRA(NS_, OP_, LP_)                                                                      \
2871	    do { if (deep) { if (extra) DS_BY_TMA(true, DCN_D, DST_D, DCM_DEEP, MINB_D, NS_, OP_, LP_); else DS_BY_TMA(false, DCN_D, DST_D, DCM_DEEP, MINB_D, NS_, OP_, LP_); } \
2872	         else      { if (extra) DS_BY_TMA(true, DCN_W, DST_W, DCM_W, 1, NS_, OP_, LP_); else DS_BY_TMA(false, DCN_W, DST_W, DCM_W, 1, NS_, OP_, LP_); } } while (0)
2873	
2874	    // NOTE (2026-07): 2-CTA/SM for tiny-M long-ctx hd128 decode was tried (env FA3_DEC2CTA) and is
2875	    // NEUTRAL -- the decode is DRAM-latency-bound at ~40% BW, and halving STAGES (5->3) to fit a 2nd
2876	    // CTA cancels the extra-warps benefit. Splitting past one wave also regresses (non-persistent tail).
2877	    // The win for this family came from the coalesced K/V gather (see prefill_kernel producer).
2878	    if (num_splits <= 1) {                  // single split -> write final O/LSE directly (no combine)
2879	        DS_BY_EXTRA(1, nullptr, nullptr);
2880	        return;
2881	    }
2882	
2883	    // LSEpart is left UNINITIALIZED (at::empty): empty/masked/padded split CTAs stamp their own -inf
2884	    // via emit_empty_lse, so we skip the per-call at::full memset (an extra fill kernel + launch).
2885	    auto fopt = q.options().dtype(at::kFloat);
2886	    at::Tensor Opart = at::empty({(long)num_splits, total_q, hq, HDV}, fopt);
2887	    at::Tensor LSEpart = at::empty({(long)num_splits, hq, total_q}, fopt);
2888	    float* opd = (float*)Opart.data_ptr(); float* lpd = (float*)LSEpart.data_ptr();
2889	    DS_BY_EXTRA(num_splits, opd, lpd);
2890	#undef DS_BY_EXTRA
2891	#undef DS_BY_TMA
2892	#undef DS_LAUNCH
2893	
2894	    dec::combine_kernel<TC, HDV><<<dim3((unsigned)(total_q * hq), (unsigned)dec::combine_nb(HDV)), dec::COMBINE_THREADS, 0, stream>>>(
2895	        opd, lpd, (TC*)out.data_ptr(), (float*)lse.data_ptr(), num_splits, total_q, hq, o_row, o_head);
2896	}
