562	template <typename T, int HD, int HDV, int CN, int CM = CTA_M>
563	__device__ __forceinline__ void qk_rs_pv_g(float (&s)[CN/2], float (&acc_o)[HDV/2], const uint32_t (&P)[CN/4],
564	                                           uint32_t sQ_wg, uint32_t sK_base, uint32_t sV_base, const float* sc) {
