571	// Final PV (last block, after the loop), HDV/CN-generic.
572	template <typename T, int HDV, int CN>
573	__device__ __forceinline__ void pv_final_g(float (&acc_o)[HDV/2], const uint32_t (&P)[CN/4], uint32_t sV_base) {
574	    pv_boxes<T, HDV, CN>(acc_o, P, sV_base);
