580	// ============================ native fp8 (e4m3) prefill path ============================
581	// QK and PV both run on the fp8 tensor core (2x bf16 throughput). The f32 accumulator layout for
582	// m64n128k32.e4m3 is identical to the bf16 m64n128k16 one, so softmax/mask/epilogue are unchanged.
583	// fp8 1-byte 128B swizzle: 128 fp8 = one 128B row; the 16-byte (16-fp8) chunk is swizzled by row&7.
584	// For hd128/CTA_N=128 every operand tile (Q,K,Vt,P) is a [128-row,128-col] K-major fp8 tile. The
585	// whole recipe (koff8 + LBO16/SBO1024/lt=1 + k32 step=kb*32 + V-transpose + P-in-smem SS-PV) is
586	// validated bit-exact vs a CPU fp8 GEMM in kernels/fp8_probe.cu.
587	__device__ __forceinline__ int koff8(int row, int c) {
588	    return (c >> 7) * (128 * CTA_N) + row * 128 + ((c & 127) ^ ((row & 7) << 4));
589	}
590	constexpr uint32_t SW8_LBO = 16, SW8_SBO = 1024;
591	__device__ __forceinline__ void wg_barrier(int id) {
592	    asm volatile("bar.sync %0, 128;\n" :: "r"(id) : "memory");
593	}
594	// FA3 warp-scheduler ping-pong primitives (mainloop_fwd_sm90_tma_gmma_ws.hpp). A named barrier with
595	// an explicit arrival count: one consumer WG `bar.sync`s it (contributes its 128 threads + blocks)
596	// while the other WG `bar.arrive`s it (contributes 128, no block). With cnt = 256 the syncing WG
597	// unblocks only once the other WG arrives -> the two consumer WGs alternate their wgmma-issue phase
598	// by one step, so while WG_a runs softmax on the SFU, WG_b feeds the tensor core (and vice-versa).
599	__device__ __forceinline__ void nb_sync(int id, int cnt) {
600	    asm volatile("bar.sync %0, %1;\n" :: "r"(id), "r"(cnt) : "memory");
601	}
602	__device__ __forceinline__ void nb_arrive(int id, int cnt) {
603	    asm volatile("bar.arrive %0, %1;\n" :: "r"(id), "r"(cnt) : "memory");
604	}
605	// QK: s[64] = Q.K^T (m64n128k32 e4m3 SS over HD; first k-block overwrites, rest accumulate).
606	template <int HDt>
607	__device__ __forceinline__ void qk_fp8_ss(float (&s)[64], uint32_t sQ_wg, uint32_t sK_base) {
608	    asm volatile("wgmma.fence.sync.aligned;\n" ::: "memory");
609	#pragma unroll
610	    for (int kb = 0; kb < HDt / 32; ++kb) {
611	        uint32_t off = (uint32_t)(kb * 32);
612	        uint64_t dA = make_smem_desc(sQ_wg + off, SW8_LBO, SW8_SBO, 1);
613	        uint64_t dB = make_smem_desc(sK_base + off, SW8_LBO, SW8_SBO, 1);
614	        int scaleD = (kb == 0) ? 0 : 1;
